<template>
  <main class="address-page">
    <header class="page-head"><div class="head-title"><RouterLink to="/dashboard" class="back" aria-label="Voltar ao dashboard"><ArrowLeft :size="20" /></RouterLink><div><span class="eyebrow">OPERAÇÃO ELEVEN</span><h1>Endereços e envios</h1><p>Do cadastro do cliente à etiqueta na impressora.</p></div></div><button class="primary" @click="newAddress"><Plus :size="17"/> Novo endereço</button></header>
    <div v-if="error" role="alert" class="alert error">{{ error }}<button @click="error=''">×</button></div><div v-if="notice" role="status" class="alert success">{{ notice }}<button @click="notice=''">×</button></div>
    <section class="metrics"><article><MapPin/><span>Endereços salvos</span><strong>{{ overview.addresses }}</strong></article><article><Printer/><span>Na fila de impressão</span><strong>{{ overview.statuses.pending || 0 }}</strong></article><article><CheckCircle2/><span>Enviados à impressora</span><strong>{{ overview.statuses.submitted || 0 }}</strong></article><article><Activity/><span>Computador da loja</span><strong class="connection">{{ online ? 'Conectado' : 'Sem conexão recente' }}</strong><small>{{ activeDevice?.name || 'Nenhuma impressora ativa' }}</small></article></section>
    <nav class="tabs" aria-label="Gestão de endereços"><button v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="changeTab(t.id)"><component :is="t.icon" :size="17"/>{{t.label}}</button></nav>
    <section v-if="tab==='addresses'" class="panel"><div class="section-head"><div><h2>Agenda de endereços</h2><p>Cadastros reutilizáveis, com ou sem vínculo a um cliente.</p></div><span class="count">{{ addresses.total }} registros</span></div><form class="toolbar" @submit.prevent="offset=0;loadAddresses()"><div class="search"><Search :size="17"/><input v-model="query" placeholder="Buscar nome, cidade, telefone…" aria-label="Buscar endereços"/></div><select v-model="country" aria-label="País" @change="offset=0;loadAddresses()"><option value="">Todos os países</option><option value="BR">Brasil</option><option value="PY">Paraguai</option></select><select v-model="showActive" aria-label="Situação" @change="offset=0;loadAddresses()"><option :value="true">Ativos</option><option :value="false">Arquivados</option></select><button type="submit">Buscar</button></form>
      <p v-if="customerFilter" class="hint">Filtrando endereços deste cliente. <button @click="customerFilter='';loadAddresses()">Mostrar todos</button></p>
      <div v-if="loading" class="empty">Carregando endereços…</div><div v-else-if="!addresses.items.length" class="empty"><MapPin :size="36"/><h3>Nenhum endereço aqui ainda</h3><p>Cadastre um destinatário ou salve uma impressão do histórico.</p><button @click="newAddress">Cadastrar endereço</button></div>
      <div v-else class="address-grid"><article v-for="a in addresses.items" :key="a.id" class="address-card"><div class="card-top"><span class="country">{{a.data.pais==='BR'?'BR · Brasil':'PY · Paraguai'}}</span><span v-if="a.cliente_id||a.pdv_cliente_id" class="linked"><Users :size="13"/> Cliente vinculado</span></div><h3>{{a.label}}</h3><strong>{{a.data.nome || 'Sem nome informado'}}</strong><p>{{[a.data.endereco,a.data.numero,a.data.bairro,a.data.complemento].filter(Boolean).join(', ') || 'Sem rua informada'}}</p><p>{{[a.data.cidade,a.data.estado,a.data.cep].filter(Boolean).join(' · ')}}</p><small>{{a.data.telefone || 'Sem telefone'}}</small><div class="card-actions"><button @click="editAddress(a)"><Pencil :size="15"/>Editar</button><button v-if="a.active" @click="openPrint(a)"><Printer :size="15"/>Imprimir</button><button v-if="a.active && a.data.pais==='BR'" @click="openFreight(a)"><Truck :size="15"/>Frete</button></div></article></div><div class="pagination"><button :disabled="offset===0" @click="offset-=30;loadAddresses()">Anterior</button><span>{{offset+1}}–{{Math.min(offset+30,addresses.total)}} de {{addresses.total}}</span><button :disabled="offset+30>=addresses.total" @click="offset+=30;loadAddresses()">Próxima</button></div>
    </section>
    <section v-if="tab==='history'" class="panel"><div class="section-head"><div><h2>Histórico de impressões</h2><p>Inclui solicitações do ERP e do bot. Enviado à impressora não confirma a saída física do papel.</p></div><button @click="loadHistory"><RefreshCw :size="16"/>Atualizar</button></div><form class="toolbar" @submit.prevent="historyOffset=0;loadHistory()"><input v-model="historyQuery" placeholder="Buscar destinatário…" aria-label="Buscar histórico"/><select v-model="historyStatus" aria-label="Estado da impressão" @change="historyOffset=0;loadHistory()"><option value="">Todos os estados</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option></select><button>Buscar</button></form><div class="table-wrap"><table><thead><tr><th>Destinatário</th><th>Solicitação</th><th>Origem</th><th>Estado</th><th>Ações</th></tr></thead><tbody><tr v-for="j in history.items" :key="j.id"><td><strong>{{j.recipient || 'Sem nome'}}</strong><small>{{j.country}} {{j.parent_id?' · Nova cópia':''}}</small></td><td>{{date(j.created_at)}}<small>{{j.user}}</small></td><td>{{j.source==='bot'?'Assistente':j.source==='superfrete'?'SuperFrete':'ERP / arquivo'}}</td><td><span class="badge" :class="j.status">{{states[j.status]||j.status}}</span></td><td><div class="row-actions"><button v-if="j.pdf_available" @click="viewJob(j.id)">PDF</button><button v-if="j.editable" @click="editJob(j)">Editar / nova cópia</button><button v-if="j.status==='pending'" @click="cancelJob(j.id)">Cancelar</button></div></td></tr><tr v-if="!history.items.length"><td colspan="5" class="empty">Nenhuma impressão encontrada.</td></tr></tbody></table></div><div class="pagination"><button :disabled="historyOffset===0" @click="historyOffset-=30;loadHistory()">Anterior</button><span>{{history.total}} impressões</span><button :disabled="historyOffset+30>=history.total" @click="historyOffset+=30;loadHistory()">Próxima</button></div></section>
    <section v-if="tab==='senders'" class="panel"><div class="section-head"><div><h2>Remetentes e endereços base</h2><p>Um único endereço para imprimir e emitir fretes.</p></div><button @click="newSender"><Plus :size="16"/>Novo remetente</button></div><div class="address-grid"><article v-for="s in senders" :key="s.id" class="address-card"><span class="country">{{s.active?'Ativo':'Arquivado'}}</span><h3>{{s.name}}</h3><p class="preline">{{s.lines.join('\n')}}</p><small>{{senderReady(s)?'Endereço pronto para impressão e frete':'Complete os campos faltantes para emitir frete'}}</small><button @click="editSender(s)"><Pencil :size="15"/>Editar remetente</button></article></div></section>
    <section v-if="tab==='layouts'" class="panel"><div class="section-head"><div><h2>Padrões de impressão</h2><p>Modelos A4 usados pelo ERP e pelo bot. Mudanças valem para novas solicitações.</p></div></div><div class="layout-grid"><form v-for="l in layouts" :key="l.id" class="layout-form" @submit.prevent="saveLayout(l)"><h3>{{l.name}}</h3><label>Título do bloco<input v-model="l.config.title" maxlength="60"/></label><div class="form-grid"><label>Tamanho da fonte<input v-model.number="l.config.font_size" type="number" min="10" max="24"/></label><label>Margem (pontos)<input v-model.number="l.config.margin" type="number" min="20" max="80"/></label><label>Fonte do remetente<input v-model.number="l.config.sender_font_size" type="number" min="9" max="20"/></label><label>Espaço do remetente<input v-model.number="l.config.sender_gap" type="number" min="10" max="100"/></label></div><label class="check"><input v-model="l.config.bold" type="checkbox"/>Destinatário em negrito</label><label>Campos e ordem</label><div v-for="(field,index) in l.config.fields" :key="field" class="field-order"><span>{{fieldLabels[field]}}</span><button type="button" :disabled="index===0" @click="moveField(l,index,-1)" aria-label="Mover campo para cima">↑</button><button type="button" :disabled="index===l.config.fields.length-1" @click="moveField(l,index,1)" aria-label="Mover campo para baixo">↓</button><button type="button" :disabled="l.config.fields.length===1" @click="l.config.fields.splice(index,1)">Ocultar</button></div><select aria-label="Adicionar campo ao modelo" @change="addField(l,$event)"><option value="">Adicionar campo…</option><option v-for="(name,key) in fieldLabels" :key="key" :value="key" :disabled="l.config.fields.includes(key)">{{name}}</option></select><button class="primary" :disabled="saving">Salvar padrão</button></form></div></section>
    <section v-if="tab==='freight'" class="panel"><div class="section-head"><div><h2>Etiquetas SuperFrete</h2><p>{{freightStatus.environment==='sandbox'?'Ambiente de testes: etiquetas sem validade para postagem.':'Ambiente de produção: emissão utiliza saldo da sua conta.'}}</p></div><span class="badge" :class="freightStatus.configured?'submitted':'pending'">{{freightStatus.configured?'Integração configurada':'Configuração pendente'}}</span></div><p v-if="!freightStatus.configured" class="hint">A integração precisa do token e do contato técnico no servidor. Seus endereços e impressões simples continuam disponíveis.</p><div class="table-wrap"><table><thead><tr><th>Destinatário</th><th>Data</th><th>Estado</th><th>Valor</th><th>Rastreio / ações</th></tr></thead><tbody><tr v-for="f in freights.items" :key="f.id"><td>{{f.recipient}}<small>{{f.environment==='sandbox'?'Teste':'Produção'}}</small></td><td>{{date(f.created_at)}}</td><td>{{freightStates[f.state]||f.state}}<small v-if="f.error" class="danger">{{f.error}}</small></td><td>{{money(f.price)}}</td><td><div class="row-actions"><code>{{f.tracking}}</code><button @click="selectedFreight=f;modal='freight-result'">Abrir</button><button v-if="f.provider_id" :disabled="saving" @click="refreshFreight(f)">Consultar</button></div></td></tr><tr v-if="!freights.items.length"><td colspan="5" class="empty">Selecione um endereço brasileiro e clique em Frete para começar.</td></tr></tbody></table></div><div class="pagination"><button :disabled="freightOffset===0" @click="freightOffset-=30;loadFreights()">Anterior</button><span>{{freights.total}} cotações e fretes</span><button :disabled="freightOffset+30>=freights.total" @click="freightOffset+=30;loadFreights()">Próxima</button></div></section>

    <div v-if="modal" class="overlay" @click.self="closeModal"><section class="dialog" role="dialog" aria-modal="true" :aria-label="modalTitle"><header><h2>{{modalTitle}}</h2><button :disabled="saving" @click="closeModal" aria-label="Fechar">×</button></header><p v-if="modalError" role="alert" class="alert error">{{modalError}}</p>
      <form v-if="modal==='address' || modal==='print'" @submit.prevent="modal==='address'?saveAddress():submitPrint()"><label v-if="modal==='address'">Identificação do endereço<input v-model="form.label" required maxlength="120" placeholder="Casa, trabalho, transportadora…"/></label><div class="customer-box" v-if="modal==='address'"><label>Vincular a cliente existente<input v-model="customerQuery" @input="searchCustomers" placeholder="Buscar nome ou telefone"/></label><div class="suggestions"><button type="button" v-for="c in customerResults" :key="c.kind+c.id" @click="linkCustomer(c)">{{c.nome}} · {{c.kind==='pdv'?'PDV':'Pedidos'}}</button></div><p v-if="form.cliente_id||form.pdv_cliente_id">Cliente vinculado {{linkedName}} <button type="button" @click="form.cliente_id=null;form.pdv_cliente_id=null;linkedName=''">Desvincular</button></p></div><AddressFields v-model="form.data"/><label v-if="modal==='address'" class="check"><input v-model="form.active" type="checkbox"/>Endereço ativo</label><template v-if="modal==='print'"><p class="hint">Uma folha A4, uma cópia. {{form.data.pais==='PY'?'Paraguai: somente os dados enviados.':'Brasil: destinatário e remetente selecionado.'}}</p><label v-if="form.data.pais==='BR'">Remetente<select v-model="senderId" required><option value="">Selecione</option><option v-for="s in activeSenders" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Impressora<select v-model="deviceId" required><option v-for="d in overview.devices.filter(d=>d.active)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><button type="button" :disabled="saving" @click="previewPrint">Conferir PDF</button><a v-if="previewUrl" :href="previewUrl" download="endereco.pdf" class="button">Baixar PDF para conferir</a><iframe v-if="previewUrl" :src="previewUrl" title="Prévia de impressão" class="pdf-preview"></iframe></template><footer><button type="button" @click="closeModal">Voltar</button><button v-if="modal==='print'" type="button" @click="modal='address';form.id='';form.version=1;form.label=form.data.nome || 'Endereço'">Salvar na agenda</button><button class="primary" :disabled="saving">{{saving?'Salvando…':modal==='address'?'Salvar endereço':'Enviar à impressora'}}</button></footer></form>
      <form v-if="modal==='sender'" @submit.prevent="saveSender"><label>Identificação no gestor<input v-model="senderForm.name" required maxlength="100"/></label><details v-if="senderForm.id"><summary>Consultar bloco salvo anteriormente</summary><p class="preline">{{senderForm.lines.join('\n')}}</p></details><label>Prévia do remetente impresso<textarea :value="senderBlock.join('\n')" rows="7" readonly></textarea></label><label class="check"><input v-model="senderForm.active" type="checkbox"/>Remetente ativo</label><h3>Endereço do remetente — impressão e SuperFrete</h3><p class="hint">Impressão e SuperFrete usam o mesmo endereço. Edite os campos abaixo: a prévia de impressão será atualizada junto. Recuperamos os dados reconhecidos nos blocos antigos; confira e complete apenas o que faltar. Pelo bot, você também pode complementar os dados na conversa.</p><AddressFields v-model="senderData" name-label="Nome do remetente"/><footer><button type="button" @click="closeModal">Voltar</button><button class="primary" :disabled="saving">Salvar remetente</button></footer></form>
      <form v-if="modal==='freight'" @submit.prevent="quoteFreight"><p>Destino: <strong>{{form.label}}</strong>. Os dados de frete precisam estar completos no endereço e no remetente.</p><label>Remetente<select v-model="senderId" required><option value="">Selecione</option><option v-for="s in activeSenders" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="form-grid"><label v-for="(name,key) in packageLabels" :key="key">{{name}}<input v-model.number="packageForm[key]" type="number" step="0.01" min="0.01" required/></label></div><h3>Conteúdo do pacote</h3><div class="product-row" v-for="(p,i) in products" :key="i"><input v-model="p.name" aria-label="Produto" placeholder="Produto" required/><input v-model.number="p.quantity" aria-label="Quantidade" type="number" min="1" required/><input v-model="p.unitary_value" aria-label="Valor unitário em reais" type="number" min="0" step="0.01" required/><button type="button" :disabled="products.length===1" @click="products.splice(i,1)">×</button></div><button type="button" @click="products.push({name:'',quantity:1,unitary_value:'0.00'})">Adicionar produto</button><label class="check"><input v-model="nonCommercial" type="checkbox"/>Envio não comercial com declaração de conteúdo</label><label v-if="!nonCommercial">Chave da nota fiscal<input v-model="invoice" pattern="[0-9]{44}" maxlength="44" required/></label><p class="hint">Informe peso e medidas reais. Cotar não realiza pagamento.</p><footer><button type="button" @click="closeModal">Voltar</button><button class="primary" :disabled="saving || !freightStatus.configured">{{saving?'Consultando…':'Cotar frete'}}</button></footer></form>
      <div v-if="modal==='freight-result' && selectedFreight"><p><strong>{{selectedFreight.recipient}}</strong> · {{freightStates[selectedFreight.state]||selectedFreight.state}}</p><p v-if="selectedFreight.environment==='sandbox'" class="hint">TESTE: esta etiqueta não serve para postagem.</p><div v-if="selectedFreight.state==='quoted'" class="rates"><button v-for="r in selectedFreight.rates" :key="r.id" :disabled="saving" @click="createCart(r.id)"><strong>{{r.name}}</strong><span>{{r.delivery_time}} dias estimados</span><b>{{money(r.price)}}</b><small>Selecionar serviço</small></button></div><div v-if="selectedFreight.state==='pending'" class="purchase"><h3>Conferir emissão</h3><p>Valor da etiqueta: <strong>{{money(selectedFreight.price)}}</strong></p><p>Ao confirmar, esse valor será debitado do saldo SuperFrete. A impressão é uma etapa separada.</p><button class="primary" :disabled="saving" @click="payFreight">{{saving?'Processando…':'Confirmar pagamento e emitir'}}</button></div><p v-if="selectedFreight.error" class="alert error">{{selectedFreight.error}}</p><p v-if="selectedFreight.tracking">Rastreio: <strong>{{selectedFreight.tracking}}</strong></p><div class="row-actions"><button v-if="selectedFreight.provider_id" :disabled="saving" @click="refreshFreight(selectedFreight)">Consultar estado / obter PDF</button><a v-if="selectedFreight.label_url" :href="selectedFreight.label_url" target="_blank" rel="noopener noreferrer" class="button">Abrir etiqueta PDF</a><button v-if="selectedFreight.label_url" :disabled="saving" @click="printLabel">Enviar etiqueta à impressora</button></div></div>
    </section></div>
  </main>
</template>

<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { RouterLink,useRoute } from 'vue-router'
import { ArrowLeft,Plus,MapPin,Printer,CheckCircle2,Activity,Search,Pencil,Users,Truck,RefreshCw,History,SlidersHorizontal } from 'lucide-vue-next'
import api from '@/services/api'
import AddressFields from '@/components/addresses/AddressFields.vue'
import type { AddressData,SavedAddress,Sender,Layout,Job,Freight,Customer,Overview } from '@/components/addresses/types'
import { blankAddress } from '@/components/addresses/types'
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const route=useRoute(),base='/api/address-manager'
const tabs=[{id:'addresses',label:'Endereços',icon:MapPin},{id:'history',label:'Impressões',icon:History},{id:'senders',label:'Remetentes',icon:Users},{id:'layouts',label:'Padrões',icon:SlidersHorizontal},{id:'freight',label:'SuperFrete',icon:Truck}]
const tab=ref('addresses'),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),modalError=ref(''),modal=ref('')
const overview=ref<Overview>({addresses:0,statuses:{},devices:[]}),addresses=ref<{total:number;items:SavedAddress[]}>({total:0,items:[]}),history=ref<{total:number;items:Job[]}>({total:0,items:[]}),senders=ref<Sender[]>([]),layouts=ref<Layout[]>([]),freights=ref<{total:number;items:Freight[]}>({total:0,items:[]})
const query=ref(''),country=ref(''),showActive=ref(true),offset=ref(0),historyOffset=ref(0),historyQuery=ref(''),historyStatus=ref(''),freightOffset=ref(0),customerFilter=ref(String(route.query.customer_id||''))
const activeDevice=computed(()=>overview.value.devices.find(d=>d.active)),online=computed(()=>!!activeDevice.value?.last_seen_at && Date.now()-new Date(activeDevice.value.last_seen_at).getTime()<90000),activeSenders=computed(()=>senders.value.filter(s=>s.active))
const emptyForm=():SavedAddress=>({id:'',label:'',data:blankAddress(),cliente_id:null,pdv_cliente_id:null,active:true,version:1})
const form=ref(emptyForm()),senderId=ref(''),deviceId=ref(''),parentId=ref<string|null>(null),requestKey=ref(crypto.randomUUID()),previewUrl=ref(''),linkedName=ref(''),customerQuery=ref(''),customerResults=ref<Customer[]>([])
const senderForm=ref<Sender>({id:'',name:'',lines:[],data:null,active:true,version:1}),senderData=ref(blankAddress('BR'))
const labelRequestKeys=new Map<string,string>()
const senderBlock=computed(()=>{const d=senderData.value;return[d.nome||senderForm.value.name,[d.endereco,d.numero].filter(Boolean).join(', '),d.bairro,d.complemento,[d.cidade,d.estado].filter(Boolean).join(' - '),d.cep?'CEP '+d.cep:'',d.cpf?'CPF/CNPJ: '+d.cpf:''].filter(Boolean)})
function senderReady(s:Sender){const d=s.data;return !!d&&d.pais==='BR'&&['nome','endereco','bairro','cidade','estado','cep'].every(k=>!!d[k as keyof AddressData])}
const freightStatus=ref({configured:false,environment:'sandbox'}),selectedFreight=ref<Freight|null>(null),packageForm=ref({weight:0,height:0,width:0,length:0}),products=ref([{name:'',quantity:1,unitary_value:'0.00'}]),nonCommercial=ref(false),invoice=ref('')
const packageLabels={weight:'Peso (kg)',height:'Altura (cm)',width:'Largura (cm)',length:'Comprimento (cm)'}
const fieldLabels:Record<string,string>={nome:'Nome',endereco:'Endereço',cidade:'Cidade / UF',cep:'CEP',pais:'País',telefone:'Telefone',cpf:'CPF'}
const states:Record<string,string>={pending:'Na fila',claimed:'Retirado pelo agente',submitted:'Enviado à impressora',uncertain:'Conferir no Windows',failed:'Falha',expired:'Expirado',cancelled:'Cancelado'}
const freightStates:Record<string,string>={quoted:'Cotado',creating:'Criando frete',pending:'Aguardando pagamento',paying:'Pagamento em andamento',released:'Etiqueta emitida',posted:'Postado',delivered:'Entregue',cancelled:'Cancelado',uncertain:'Conferência necessária'}
const modalTitle=computed(()=>({'address':form.value.id?'Editar endereço':'Novo endereço','print':'Conferir impressão','sender':'Remetente','freight':'Cotar envio','freight-result':'Etiqueta SuperFrete'}[modal.value]||''))
const date=(v:string)=>new Date(v).toLocaleString('pt-BR'),money=(v:string|null|undefined)=>v==null?'—':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
function explain(e:unknown){const d=(e as {response?:{data?:{detail?:unknown}}}).response?.data?.detail;return typeof d==='string'?d:Array.isArray(d)?d.map(x=>x.msg).join('; '):'Não foi possível concluir. Tente novamente.'}
async function act(fn:()=>Promise<void>){saving.value=true;modalError.value='';error.value='';try{await fn()}catch(e){if(modal.value)modalError.value=explain(e);else error.value=explain(e)}finally{saving.value=false}}
async function loadAddresses(){loading.value=true;try{addresses.value=(await api.get(base+'/addresses',{params:{q:query.value,country:country.value,active:showActive.value,offset:offset.value,customer_id:customerFilter.value||undefined}})).data}catch(e){error.value=explain(e)}finally{loading.value=false}}
async function loadHistory(){try{history.value=(await api.get(base+'/history',{params:{q:historyQuery.value,status:historyStatus.value,offset:historyOffset.value}})).data}catch(e){error.value=explain(e)}}
async function loadFreights(){try{freights.value=(await api.get('/api/freight/orders',{params:{offset:freightOffset.value}})).data}catch(e){error.value=explain(e)}}
async function loadOverview(){overview.value=(await api.get(base+'/overview')).data;if(!deviceId.value)deviceId.value=activeDevice.value?.id||''}
async function init(){try{await Promise.all([loadOverview(),loadAddresses(),api.get(base+'/senders').then(r=>senders.value=r.data),api.get(base+'/layouts').then(r=>layouts.value=r.data),api.get('/api/freight/status').then(r=>freightStatus.value=r.data)])}catch(e){error.value=explain(e)}}
function changeTab(t:string){tab.value=t;if(t==='history')loadHistory();if(t==='freight')loadFreights()}
function closeModal(){if(saving.value)return;modal.value='';modalError.value='';if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
function newAddress(){form.value=emptyForm();customerResults.value=[];customerQuery.value='';linkedName.value='';modal.value='address';modalError.value=''}
function editAddress(a:SavedAddress){form.value=clone(a);linkedName.value='';customerResults.value=[];modal.value='address';modalError.value=''}
let searchTimer:ReturnType<typeof setTimeout>|undefined;let searchSeq=0
function searchCustomers(){clearTimeout(searchTimer);const seq=++searchSeq;searchTimer=setTimeout(async()=>{try{const r=await api.get(base+'/customers',{params:{q:customerQuery.value}});if(seq===searchSeq)customerResults.value=r.data}catch(e){modalError.value=explain(e)}},300)}
function linkCustomer(c:Customer){form.value.cliente_id=c.kind==='pedidos'?c.id:null;form.value.pdv_cliente_id=c.kind==='pdv'?c.id:null;linkedName.value=c.nome;form.value.data.nome ||= c.nome;form.value.data.telefone ||= c.telefone||'';form.value.data.cpf ||= c.cpf||'';form.value.data.endereco ||= c.endereco||'';customerResults.value=[];customerQuery.value=''}
async function saveAddress(){await act(async()=>{const {id,label,data,cliente_id,pdv_cliente_id,active,version}=form.value;const body={label,data,cliente_id,pdv_cliente_id,active,version};if(id)await api.put(base+'/addresses/'+id,body);else await api.post(base+'/addresses',body);modal.value='';notice.value='Endereço salvo.';await Promise.all([loadAddresses(),loadOverview()])})}
function openPrint(a:SavedAddress){form.value=clone(a);senderId.value='';parentId.value=null;requestKey.value=crypto.randomUUID();modal.value='print';modalError.value='';previewUrl.value=''}
function printBody(){return{request_key:requestKey.value,address_id:form.value.id||null,device_id:deviceId.value,sender_id:senderId.value||null,data:form.value.data,parent_id:parentId.value}}
async function previewPrint(){await act(async()=>{const r=await api.post(base+'/preview',printBody(),{responseType:'blob'});if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=URL.createObjectURL(r.data)})}
async function submitPrint(){await act(async()=>{await api.post(base+'/print',printBody());modal.value='';notice.value='Uma cópia enviada à fila da loja.';await loadOverview();if(tab.value==='history')await loadHistory()})}
async function viewJob(id:string){await act(async()=>{const r=await api.get(base+'/history/'+id+'/pdf',{responseType:'blob'});const u=URL.createObjectURL(r.data);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)})}
async function editJob(j:Job){await act(async()=>{const {data:d}=await api.get(base+'/history/'+j.id);const p=d.snapshot;form.value={...emptyForm(),label:p.endereco.nome||'Endereço',data:p.editor||{...blankAddress(p.endereco.pais),...p.endereco}};delete (form.value.data as AddressData & {remetente?:string}).remetente;parentId.value=j.id;senderId.value=p.sender_id||p.endereco.remetente||'';deviceId.value=d.device_id;requestKey.value=crypto.randomUUID();modal.value='print'})}
async function cancelJob(id:string){await act(async()=>{await api.post(base+'/history/'+id+'/cancel');await Promise.all([loadHistory(),loadOverview()])})}
function newSender(){senderForm.value={id:'',name:'',lines:[],data:null,active:true,version:1};senderData.value=blankAddress('BR');modal.value='sender';modalError.value=''}
function editSender(s:Sender){senderForm.value=clone(s);senderData.value=s.data?clone(s.data):{...blankAddress('BR'),nome:s.name};modal.value='sender';modalError.value=''}
async function saveSender(){await act(async()=>{const {id,...rest}=senderForm.value;const b={...rest,lines:senderBlock.value,data:{...senderData.value,nome:senderData.value.nome||senderForm.value.name}};if(id)await api.put(base+'/senders/'+id,b);else await api.post(base+'/senders',b);senders.value=(await api.get(base+'/senders')).data;modal.value='';notice.value='Remetente salvo. Novas impressões usarão os dados atualizados.'})}
function moveField(l:Layout,i:number,delta:number){const next=[...l.config.fields];[next[i],next[i+delta]]=[next[i+delta]!,next[i]!];l.config.fields=next}
function addField(l:Layout,event:Event){const el=event.target as HTMLSelectElement;if(el.value)l.config.fields.push(el.value);el.value=''}
async function saveLayout(l:Layout){await act(async()=>{const r=await api.put(base+'/layouts/'+l.id,{name:l.name,config:l.config,version:l.version});l.version=r.data.version;notice.value='Padrão salvo para novas impressões do ERP e do bot.'})}
function openFreight(a:SavedAddress){form.value=clone(a);senderId.value='';requestKey.value=crypto.randomUUID();modal.value='freight';modalError.value=''}
async function quoteFreight(){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/quotes',{request_key:requestKey.value,address_id:form.value.id,sender_id:senderId.value,package:packageForm.value,products:products.value,non_commercial:nonCommercial.value,invoice:invoice.value})).data;modal.value='freight-result';await loadFreights()})}
async function createCart(service:number){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+selectedFreight.value!.id+'/cart',{service})).data;await loadFreights()})}
async function payFreight(){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+selectedFreight.value!.id+'/pay',{expected_price:selectedFreight.value!.price})).data;await loadFreights()})}
async function refreshFreight(f:Freight){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+f.id+'/refresh')).data;await loadFreights()})}
async function printLabel(){await act(async()=>{const id=selectedFreight.value!.id;const key=labelRequestKeys.get(id)||crypto.randomUUID();labelRequestKeys.set(id,key);await api.post('/api/freight/orders/'+id+'/print',{device_id:deviceId.value,request_key:key});labelRequestKeys.delete(id);notice.value='Etiqueta enviada à impressora.';modal.value='';await loadOverview()})}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{init();timer=setInterval(()=>{loadOverview().catch(()=>{});if(tab.value==='history')loadHistory()},20000)})
onUnmounted(()=>{clearInterval(timer);clearTimeout(searchTimer);if(previewUrl.value)URL.revokeObjectURL(previewUrl.value)})
</script>

