f1f2;color:#9f1239}.success{background:#ecfdf5;color:#166534}.danger{color:#9f1239}.preline{white-space:pre-line}.layout-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px}.layout-form{border:1px solid #e2e8f0;padding:20px;border-radius:12px}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:600;color:#475569;margin:13px 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}.check{display:flex;flex-direction:row;align-items:center}.field-order{display:flex;gap:5px;align-items:center;padding:6px 0}.field-order span{flex:1;font-size:13px}.field-order button{padding:4px 8px;font-size:11px}.layout-form>select{width:100%;margin:12px 0}.overlay{position:fixed;inset:0;background:#0f172a88;z-index:1000;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(3px)}.dialog{width:740px;max-width:100%;max-height:92vh;overflow-y:auto;background:white;border-radius:16px;padding:25px;box-shadow:0 20px 60px #0003}.dialog>header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e2e8f0;padding-bottom:15px}.dialog footer{justify-content:flex-end;border-top:1px solid #e2e8f0;padding-top:18px;margin-top:20px;flex-wrap:wrap}.customer-box{background:#f8fafc;padding:1px 15px 12px;border-radius:10px}.suggestions{display:flex;flex-wrap:wrap;gap:5px}.pdf-preview{width:100%;height:420px;margin-top:15px;border:1px solid #ddd}.product-row{display:grid;grid-template-columns:3fr 1fr 1fr auto;gap:6px;margin-bottom:9px}.rates{display:grid;gap:12px}.rates button{justify-content:space-between;flex-wrap:wrap;padding:18px}.purchase{background:#eff6ff;border-radius:12px;padding:20px;margin:16px 0}summary{cursor:pointer;color:#2563eb;margin:20px 0}code{font-size:12px;overflow-wrap:anywhere}@media(max-width:1000px){.address-grid{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:1fr 1fr}}@media(max-width:640px){.address-page{padding:20px 12px}.page-head{align-items:start;gap:10px}.page-head>button{font-size:0}.page-head>button svg{width:20px}h1{font-size:22px}.head-title{gap:10px}.panel{padding:15px}.address-grid,.layout-grid{grid-template-columns:1fr}.metrics{gap:9px}.metrics article{padding:15px}.metrics strong{font-size:23px}.metrics .connection{font-size:13px}.tabs button{padding:12px}.dialog{padding:17px}.overlay{padding:8px}.form-grid{grid-template-columns:1fr 1fr}.product-row{grid-template-columns:2fr 1fr 1fr auto}.section-head{align-items:start}.section-head p{font-size:12px}.pagination{justify-content:space-between}.toolbar>input{width:100%}}
